  "c3-worker-python": {"id":"c3-worker-python","name":"Worker (Python) — official","description":"Cloudflare’s official Python Worker starter, generated with create-cloudflare.","type":"worker","category":"python","deployCommand":"deploy","buildCommand":"","requiresRoute":false,"source":"local","deploy":{"runtime":"python","setup":"npm install","command":"uv run pywrangler deploy"}},
  "c3-worker-ts": {"id":"c3-worker-ts","name":"Worker (TypeScript) — official","description":"Cloudflare’s official TypeScript Worker starter, generated with create-cloudflare.","type":"worker","category":"typescript","deployCommand":"deploy","buildCommand":"","requiresRoute":false,"source":"local","deploy":{"setup":"npm install","command":"deploy"}},
  "node-express": {"id":"node-express","name":"Node.js Express (Worker)","description":"An Express app running on Cloudflare Workers via nodejs_compat. Routes, JSON, and middleware work as usual.","type":"worker","category":"framework","deployCommand":"deploy","buildCommand":"","requiresRoute":false},
